/*
 * HSD data the PC build must define with its C type rather than as generated bytes (tools/local/port/pcdata.py keeps
 * them as raw big-endian bytes, "unsure", because the decomp declares them in more than one way). They hold function
 * pointers or native structs, so on the PC they must be real C objects: the class-info tables (only `info_init` is set
 * in the original data; the rest is filled at run time by that function), the state-invalidate callback table, and
 * structs the code reads natively. Values are taken from the original data (the relocations pcdata.py reports).
 *
 * Test-local for now. The proper home is src/hsd (data ownership: these tables belong to the HSD units that use them);
 * moving them there needs split changes, which go through Main.
 */
#include "dolphin/types.h"
#include "dolphin/gx.h"
#include "hsd/hsd_class.h"
#include "hsd/hsd_dobj.h"
#include "hsd/hsd_wobj.h"
#include "hsd/hsd_objalloc.h"
#include "hsd/hsd_state.h"

#include <string.h>

void ObjInfoInit_801AA568(void);
void WObjInfoInit(void);
void DObjInfoInit(void);
void fn_801B2718(void);
void fn_801B26F8(void);
void fn_801B31F4(void);
void fn_801B31A4(void);
void fn_801B3174(void);
void fn_801B3168(void);
void fn_801B2654(void);

HSD_ClassInfo hsdObj = {.head = {.info_init = ObjInfoInit_801AA568}};               /* 0x8036CC00 */
HSD_WObjInfo lbl_8036C5F0 = {.parent = {.parent = {.head = {.info_init = WObjInfoInit}}}}; /* WObj class */
HSD_DObjInfo lbl_8036C7A0 = {.parent = {.head = {.info_init = DObjInfoInit}}};      /* DObj class */

/* HSD_StateInvalidate's table: one callback per state bit (state.c / tev.c), ended by a zero mask */
HSD_StateInvalidateEntry lbl_8036CFA8[8] = {
    {0x01, fn_801B2718}, {0x02, fn_801B26F8}, {0x04, fn_801B31F4}, {0x08, fn_801B31A4},
    {0x10, fn_801B3174}, {0x20, fn_801B3168}, {0x40, fn_801B2654}, {0, NULL},
};

u32 lbl_8036CC40[0x90 / 4];          /* HSD_PerfStat counters (all zero at start) */
HSD_ObjAllocData lbl_80465378;       /* fobj_alloc_data (zero at start) */
HSD_DObj* lbl_8047B264;              /* zero at start */

/* GXNtsc480IntDf in the original data (initialize.c's default render mode); a copy of Aurora's at startup */
GXRenderModeObj lbl_80312D30;

void pc_hsd_data_init(void) {
    memcpy(&lbl_80312D30, &GXNtsc480IntDf, sizeof(GXRenderModeObj));
}
